  ON CONFLICT(project_id) DO UPDATE SET open_sessions=open_sessions+excluded.open_sessions,prompts=prompts+excluded.prompts,tool_calls=tool_calls+excluded.tool_calls; INSERT INTO project_session_days(project_id,day,n) VALUES(NEW.project_id,NEW.occurred_day,1)
  ON CONFLICT(project_id,day) DO UPDATE SET n=n+1; END;

CREATE TRIGGER IF NOT EXISTS session_statistics_counted AFTER UPDATE OF open_session,prompts,tool_calls ON session_statistics WHEN OLD.open_session IS NOT NEW.open_session OR OLD.prompts IS NOT NEW.prompts OR OLD.tool_calls IS NOT NEW.tool_calls BEGIN INSERT INTO project_session_counts(project_id,open_sessions,prompts,tool_calls) VALUES(NEW.project_id,NEW.open_session-OLD.open_session,NEW.prompts-OLD.prompts,NEW.tool_calls-OLD.tool_calls)
  ON CONFLICT(project_id) DO UPDATE SET open_sessions=open_sessions+excluded.open_sessions,prompts=prompts+excluded.prompts,tool_calls=tool_calls+excluded.tool_calls; END;

CREATE TRIGGER IF NOT EXISTS session_statistics_day AFTER UPDATE OF occurred_day ON session_statistics WHEN OLD.occurred_day IS NOT NEW.occurred_day BEGIN INSERT INTO project_session_days(project_id,day,n) VALUES(OLD.project_id,OLD.occurred_day,-1)
  ON CONFLICT(project_id,day) DO UPDATE SET n=n-1; INSERT INTO project_session_days(project_id,day,n) VALUES(NEW.project_id,NEW.occurred_day,1)
  ON CONFLICT(project_id,day) DO UPDATE SET n=n+1; END;

CREATE TRIGGER IF NOT EXISTS session_statistics_delete AFTER DELETE ON session_statistics BEGIN INSERT INTO project_session_counts(project_id,open_sessions,prompts,tool_calls) VALUES(OLD.project_id,-OLD.open_session,-OLD.prompts,-OLD.tool_calls)
  ON CONFLICT(project_id) DO UPDATE SET open_sessions=open_sessions+excluded.open_sessions,prompts=prompts+excluded.prompts,tool_calls=tool_calls+excluded.tool_calls; INSERT INTO project_session_days(project_id,day,n) VALUES(OLD.project_id,OLD.occurred_day,-1)
  ON CONFLICT(project_id,day) DO UPDATE SET n=n-1; END;

CREATE TRIGGER IF NOT EXISTS session_attachment_counts_insert AFTER INSERT ON session_attachment_counts BEGIN INSERT INTO project_session_counts(project_id,attachments) VALUES(NEW.project_id,NEW.n)
  ON CONFLICT(project_id) DO UPDATE SET attachments=attachments+excluded.attachments; END;

CREATE TRIGGER IF NOT EXISTS session_attachment_counts_update AFTER UPDATE OF n ON session_attachment_counts WHEN OLD.n IS NOT NEW.n BEGIN INSERT INTO project_session_counts(project_id,attachments) VALUES(NEW.project_id,NEW.n-OLD.n)
  ON CONFLICT(project_id) DO UPDATE SET attachments=attachments+excluded.attachments; END;

CREATE TRIGGER IF NOT EXISTS session_attachment_counts_delete AFTER DELETE ON session_attachment_counts BEGIN INSERT INTO project_session_counts(project_id,attachments) VALUES(OLD.project_id,-OLD.n)
  ON CONFLICT(project_id) DO UPDATE SET attachments=attachments+excluded.attachments; END;

INSERT INTO projection_catchup(projection,phase,done) SELECT 'project_statistics','projectStatisticsSessions',NOT EXISTS(SELECT 1 FROM sessions) ON CONFLICT DO NOTHING;

INSERT INTO projection_catchup(projection,phase,done) SELECT 'project_statistics','projectStatisticsAttachments',NOT EXISTS(SELECT 1 FROM attachments) ON CONFLICT DO NOTHING;

INSERT OR REPLACE INTO schema_meta (key, value) VALUES ('version', '776');
